13 // Directed Random Verification Testbench for `axi_lite_regs`.
14 
15 `include "axi/assign.svh"
16 
17 /// Testbench for validating the module `axi_lite_regs`.
18 module tb_axi_lite_regs #(
19   /// Define the parameter `RegNumBytes` of the DUT.
20   parameter int unsigned            RegNumBytes  = 32'd200,
21   /// Define the parameter `AxiReadOnly` of the DUT.
22   parameter logic [RegNumBytes-1:0] AxiReadOnly  = {{RegNumBytes-18{1'b0}}, 18'b101110111111000000},
23   /// Define the parameter `PrivProtOnly` of the DUT.
24   parameter bit                     PrivProtOnly = 1'b0,
25   /// Define the parameter `SecuProtOnly` of the DUT.
26   parameter bit                     SecuProtOnly = 1'b0,
27   /// Number of random writes generated by the testbench AXI4-Lite random master.
28   parameter int unsigned            NoWrites     = 32'd1000,
29   /// Number of random reads generated by the testbench AXI4-Lite random master.
30   parameter int unsigned            NoReads      = 32'd1500
31 );
32   // AXI configuration
33   localparam int unsigned AxiAddrWidth = 32'd32;    // Axi Address Width
34   localparam int unsigned AxiDataWidth = 32'd32;    // Axi Data Width
35   localparam int unsigned AxiStrbWidth = AxiDataWidth / 32'd8;
36   // timing parameters
37   localparam time CyclTime = 10ns;
38   localparam time ApplTime =  2ns;
39   localparam time TestTime =  8ns;
40 
41   typedef logic [7:0]              byte_t;
42   typedef logic [AxiAddrWidth-1:0] axi_addr_t;
43   typedef logic [AxiDataWidth-1:0] axi_data_t;
44   typedef logic [AxiStrbWidth-1:0] axi_strb_t;
45 
46   localparam axi_addr_t StartAddr = axi_addr_t'(0);
47   localparam axi_addr_t EndAddr   =
48       axi_addr_t'(StartAddr + RegNumBytes + RegNumBytes/5);
49 
50   localparam byte_t [RegNumBytes-1:0] RegRstVal = '0;
51 
52   typedef axi_test::rand_axi_lite_master #(
53     // AXI interface parameters
54     .AW ( AxiAddrWidth ),
55     .DW ( AxiDataWidth ),
56     // Stimuli application and test time
57     .TA ( ApplTime  ),
58     .TT ( TestTime  ),
59     .MIN_ADDR ( StartAddr ),
60     .MAX_ADDR ( EndAddr   ),
61     .MAX_READ_TXNS  ( 10 ),
62     .MAX_WRITE_TXNS ( 10 )
63   ) rand_lite_master_t;
64 
65   // -------------
66   // DUT signals
67   // -------------
68   logic clk;
69   // DUT signals
70   logic rst_n;
71   logic end_of_sim;
72   // Register signals
73   byte_t [RegNumBytes-1:0] reg_d,     reg_q;
74   logic  [RegNumBytes-1:0] wr_active, rd_active, reg_load;
75 
76   // -------------------------------
77   // AXI Interfaces
78   // -------------------------------
79   AXI_LITE #(
80     .AXI_ADDR_WIDTH ( AxiAddrWidth      ),
81     .AXI_DATA_WIDTH ( AxiDataWidth      )
82   ) master ();
83   AXI_LITE_DV #(
84     .AXI_ADDR_WIDTH ( AxiAddrWidth      ),
85     .AXI_DATA_WIDTH ( AxiDataWidth      )
86   ) master_dv (clk);
87   `AXI_LITE_ASSIGN(master, master_dv)
88 
89   // -------------------------------
90   // AXI Rand Masters and Slaves
91   // -------------------------------
92   // Masters control simulation run time
93   initial begin : proc_generate_axi_traffic
94     automatic rand_lite_master_t lite_axi_master = new ( master_dv, "Lite Master");
95     automatic axi_data_t      data = '0;
96     automatic axi_pkg::resp_t resp = '0;
97     end_of_sim <= 1'b0;
98     lite_axi_master.reset();
99     @(posedge rst_n);
100     repeat (5) @(posedge clk);
101     // Test known register.
102     // Write to it.
103     lite_axi_master.write(axi_addr_t'(32'h0000_0000), axi_pkg::prot_t'('0),
104         axi_data_t'(64'hDEADBEEFDEADBEEF), axi_strb_t'(8'hFF), resp);
105     if (PrivProtOnly || SecuProtOnly) begin
106       assert (resp == axi_pkg::RESP_SLVERR) else
107           $fatal(1, "PrivProtOnly || SecuProtOnly: Unprivileged access was falsely granted.");
108     end else begin
109       assert (resp == axi_pkg::RESP_OKAY) else
110           $fatal(1, "Access should be granted");
111     end
112     // Read from it.
113     lite_axi_master.read(axi_addr_t'(32'h0000_0000), axi_pkg::prot_t'('0), data, resp);
114     if (PrivProtOnly || SecuProtOnly) begin
115       // Expect error response
116       assert (resp == axi_pkg::RESP_SLVERR) else
117           $fatal(1, "PrivProtOnly || SecuProtOnly: Unprivileged access was falsely granted.");
118       assert (data == axi_data_t'(32'hBA5E1E55)) else
119           $fatal(1, "Data is unexpected, should be axi_data_t'(32'hBA5E1E55).");
120     end else begin
121       assert (resp == axi_pkg::RESP_OKAY) else
122           $fatal(1, "Access should be granted.");
123       assert (data == axi_data_t'(64'hDEADBEEFDEADBEEF)) else
124           $fatal(1, "Data is unexpected, should be axi_data_t'(64'hDEADBEEFDEADBEEF).");
125     end
126 
127     // Let random stimuli application checking is separate.
128     lite_axi_master.run(NoReads, NoWrites);
129     end_of_sim <= 1'b1;
130   end
131 
132   initial begin : proc_generate_direct_load
133     for (int unsigned i = 0; i < RegNumBytes; i++) begin
134       automatic int unsigned j = i;
135       fork
136         toggle_load(j);
137       join_none
138     end
139   end
140 
141   task automatic toggle_load(int unsigned byte_i);
142     byte_t       rand_val;
143     int unsigned rand_wait;
144     @(posedge rst_n);
145     reg_load[byte_i] = 1'b0;
146     reg_d[byte_i]    = 8'h00;
147     @(posedge clk);
148     forever begin
149       rand_wait = $urandom_range(0, 20);
150       repeat (rand_wait) @(posedge clk);
151       rand_val          = byte_t'($urandom());
152       reg_d[byte_i]    <= #ApplTime rand_val;
153       reg_load[byte_i] <= #ApplTime 1'b1;
154       @(posedge clk);
155       reg_d[byte_i]    <= #ApplTime '0;
156       reg_load[byte_i] <= #ApplTime 1'b0;
157     end
158   endtask : toggle_load
159 
160   initial begin : proc_check_read_data
161     automatic axi_data_t      exp_rdata[$];
162     automatic axi_pkg::resp_t exp_resp[$];
163 
164     @(posedge rst_n);
165     forever begin
166       @(posedge clk);
167       #(TestTime);
168 
169       // Push the expected data back.
170       if (master.ar_valid && master.ar_ready) begin
171         automatic int unsigned ar_idx = ((master.ar_addr - StartAddr)
172             >> $clog2(AxiStrbWidth) << $clog2(AxiStrbWidth));
173         automatic axi_data_t      r_data = axi_data_t'(0);
174         automatic axi_pkg::resp_t r_resp = axi_pkg::RESP_SLVERR;
175         for (int unsigned i = 0; i < AxiStrbWidth; i++) begin
176           if ((ar_idx+i) < RegNumBytes) begin
177             r_data[8*i+:8] = reg_q[ar_idx+i];
178             r_resp         = axi_pkg::RESP_OKAY;
179           end else begin
180             r_data[8*i+:8] = 8'hxx;
181           end
182         end
183         // check the right protection access
184         if (PrivProtOnly && !master.ar_prot[0]) begin
185           r_resp = axi_pkg::RESP_SLVERR;
186         end
187         if (SecuProtOnly && !master.ar_prot[1]) begin
188           r_resp = axi_pkg::RESP_SLVERR;
189         end
190         exp_resp.push_back(r_resp);
191         exp_rdata.push_back(r_data);
192       end
193 
194       // compare data if there is a value expected
195       if (master.r_valid && master.r_ready) begin
196         automatic axi_data_t r_data = exp_rdata.pop_front();
197         if (master.r_resp == axi_pkg::RESP_OKAY) begin
198           for (int unsigned i = 0; i < AxiStrbWidth; i++) begin
199             automatic byte_t exp_byte = r_data[8*i+:8];
200             if (exp_byte !== 8'hxx) begin
201               assert (master.r_data[8*i+:8] == exp_byte) else
202                   $error("Unexpected read data: exp: %0h observed: %0h", r_data, master.r_data);
203               assert (master.r_resp == axi_pkg::RESP_OKAY);
204             end
205           end
206         end else if (master.r_resp == axi_pkg::RESP_SLVERR) begin
207           assert (master.r_data == axi_data_t'(32'hBA5E1E55));
208         end else begin
209           $error("Slave responded with false response: %0h", master.r_resp);
210         end
211       end
212     end
213   end
214 
215   axi_pkg::resp_t b_resp_queue[$];
216 
217   // Only works as module expects both AW & W valid before it does something
218   initial begin : proc_check_write_data
219     @(posedge rst_n);
220     forever begin
221       #TestTime;
222       // AW and W is launched, setup the test tasks
223       if (master.aw_valid && master.aw_ready && master.w_valid && master.w_ready) begin
224         automatic int unsigned aw_idx = ((master.aw_addr - StartAddr)
225             >> $clog2(AxiStrbWidth) << $clog2(AxiStrbWidth));
226         automatic axi_pkg::resp_t exp_b_resp = (aw_idx < RegNumBytes) ?
227             axi_pkg::RESP_OKAY : axi_pkg::RESP_SLVERR;
228         automatic bit all_ro = 1'b1;
229         // check for errors from wrong access protection
230         if (PrivProtOnly && !master.aw_prot[0]) begin
231           exp_b_resp = axi_pkg::RESP_SLVERR;
232         end
233         if (SecuProtOnly && !master.aw_prot[1]) begin
234           exp_b_resp = axi_pkg::RESP_SLVERR;
235         end
236         // Check if all accesses bytes are read only
237         for (int unsigned i = 0; i < AxiStrbWidth; i++) begin
238           if (!AxiReadOnly[aw_idx+i]) begin
239             all_ro = 1'b0;
240           end
241         end
242         if (all_ro) begin
243           exp_b_resp = axi_pkg::RESP_SLVERR;
244         end
245 
246         // do the actual write checking
247         if (exp_b_resp == axi_pkg::RESP_OKAY) begin
248           // go through every byte
249           for (int unsigned i = 0; i < AxiStrbWidth; i++) begin
250             if ((aw_idx+i) < RegNumBytes) begin
251               if (master.w_strb[i]) begin
252                 automatic int unsigned        j = aw_idx + i;
253                 automatic byte_t       exp_byte = master.w_data[8*i+:8];
254                 fork
255                   check_q(j, exp_byte);
256                 join_none
257               end
258               assert (master.w_strb[i] == wr_active[aw_idx+i]);
259             end
260           end
261         end
262         b_resp_queue.push_back(exp_b_resp);
263       end
264       @(posedge clk);
265     end
266   end
267 
268   initial begin : proc_check_b
269     automatic axi_pkg::resp_t exp_b_resp;
270     @(posedge rst_n);
271     forever begin
272       #TestTime;
273       if (master.b_valid && master.b_ready) begin
274         if (b_resp_queue.size()) begin
275           exp_b_resp = b_resp_queue.pop_front();
276           assert (exp_b_resp == master.b_resp) else
277               $error("Unexpected B response: EXP: %b ACT: %b", exp_b_resp, master.b_resp);
278         end else begin
279           $error("B response even no AW was sent.");
280         end
281       end
282       @(posedge clk);
283     end
284   end
285 
286   // check that the expected register byte has been written
287   task automatic check_q(int unsigned byte_i, byte_t exp_byte);
288     automatic byte_t save_byte = (reg_load[byte_i]) ? reg_d[byte_i] : reg_q[byte_i];
289     @(posedge clk);
290     #TestTime;
291     if (!AxiReadOnly[byte_i]) begin
292       assert(exp_byte == reg_q[byte_i]) else
293           $error("AXI write was not registered at byte: %0d", byte_i);
294     end else begin
295       assert (reg_q[byte_i] == save_byte) else
296           $error("AXI write onto read only byte: %0d SAVE: %h EXP: %h ACT %h",
297               byte_i, save_byte, exp_byte, reg_q[byte_i]);
298     end
299   endtask : check_q
300 
301   // Some assertions for additional checking.
302   default disable iff (~rst_n);
303   for (genvar i = 0; i < RegNumBytes; i++) begin : gen_check_ro_bytes
304     if (AxiReadOnly[i]) begin : gen_check_ro
305       ro_assert_no_load: assert property (@(posedge clk)
306           ((wr_active[i] && !reg_load[i]) |=> $stable(reg_q[i]))) else
307           $fatal(1, "ReadOnly byte %0d changed from AXI write, while not direct loaded.", i);
308       ro_assert_load: assert property (@(posedge clk)
309           ((wr_active[i] && reg_load[i]) |=> (reg_q[i] === $past(reg_d[i])))) else
310           $fatal(1, "ReadOnly byte %0d changed from AXI write, while direct loaded.", i);
311     end
312     load_assert_no_axi: assert property (@(posedge clk)
313         (reg_load[i] && !AxiReadOnly[i] |-> !wr_active[i])) else
314         $fatal(1, "Byte %0d, AXI write onto non read-only and direct load are both active!", i);
315     load_assert_data:   assert property (@(posedge clk)
316         (reg_load[i] |=> reg_q[i] === $past(reg_d[i]))) else
317         $fatal(1, "Byte %0d, direct load was executed falsely.", i);
318     stable_assert:      assert property (@(posedge clk)
319         (!reg_load[i] && !wr_active[i]) |=> $stable(reg_q[i])) else
320         $fatal(1, "Byte %0d is unstable, when no AXI write or direct load.", i);
321   end
322 
323   initial begin : proc_stop_sim
324     wait (end_of_sim);
325     repeat (1000) @(posedge clk);
326     $display("Simulation stopped as Master transferred its data.");
327     $stop();
328   end
329 
330   //-----------------------------------
331   // Clock generator
332   //-----------------------------------
333   clk_rst_gen #(
334     .CLK_PERIOD    ( CyclTime ),
335     .RST_CLK_CYCLES( 5        )
336   ) i_clk_gen (
337     .clk_o (clk),
338     .rst_no(rst_n)
339   );
340 
341   //-----------------------------------
342   // DUT
343   //-----------------------------------
344   axi_lite_regs_intf #(
345     .REG_NUM_BYTES  ( RegNumBytes  ),
346     .AXI_ADDR_WIDTH ( AxiAddrWidth ),
347     .AXI_DATA_WIDTH ( AxiDataWidth ),
348     .PRIV_PROT_ONLY ( PrivProtOnly ),
349     .SECU_PROT_ONLY ( SecuProtOnly ),
350     .AXI_READ_ONLY  ( AxiReadOnly  ),
351     .REG_RST_VAL    ( RegRstVal    )
352   ) i_axi_lite_regs (
353     .clk_i       ( clk       ),
354     .rst_ni      ( rst_n     ),
355     .slv         ( master    ),
356     .wr_active_o ( wr_active ),
357     .rd_active_o ( rd_active ),
358     .reg_d_i     ( reg_d     ),
359     .reg_load_i  ( reg_load  ),
360     .reg_q_o     ( reg_q     )
361   );
362 endmodule
</code>
